#!/usr/bin/env bash
set -Eeuo pipefail
umask 027

PHASE="TST-5D-W2B-I2F-3E-J-R2-R8"
REPO_ROOT="/home/deploy/ai_media_os"
PYTHON_BIN="${REPO_ROOT}/.venv/bin/python"

BASE_REL="exchange/review_evidence/slack_worker_release_rebinding/slack-worker-CANDIDATE-NOT-APPROVED-01ba8809f133/tst-5d-w2b-i2e-baseline-absorption-rereview-20260725T141632"
SOURCE_REL="${BASE_REL}/i2f3e-j-r2-r7-evidence-seal-correction-20260726T012717Z-523349"
SOURCE_ROOT="${REPO_ROOT}/${SOURCE_REL}"

RUN_ID="$(date -u +%Y%m%dT%H%M%SZ)-$$"
EVIDENCE_REL="${BASE_REL}/i2f3e-j-r2-r8-root-readonly-verification-packet-preparation-${RUN_ID}"
EVIDENCE_ROOT="${REPO_ROOT}/${EVIDENCE_REL}"
PACKET_ROOT="${EVIDENCE_ROOT}/packet-snapshot"
CANDIDATE_ROOT="${PACKET_ROOT}/candidate-artifacts"
LOG_ROOT="${EVIDENCE_ROOT}/validation-logs"

if [[ "$(id -u)" -eq 0 ]]; then
  echo "ROOT_EXECUTION_FORBIDDEN=true" >&2
  exit 1
fi

test -x "$PYTHON_BIN"
test -d "$SOURCE_ROOT"
test -x /usr/bin/sudo
test -x /usr/bin/id
test -x /usr/bin/test
test -x /usr/bin/stat

cd "$REPO_ROOT"

sha256sum -c <<'SOURCE_SHAS'
ff696c3857c9b9624ec8bb76b7eb668f2a90285825711f4cb3fdcbcc48f048c1  ${SOURCE_REL}/result.json
a8927081753839939f752256fa7edbe0dbad1816341cb34a32484a325ab96e1d  ${SOURCE_REL}/seal-validation.json
d6b71537bae70fa0f4e9ae2a6b9b214881ec11e0190e440782c9da0a71d9afc3  ${SOURCE_REL}/snapshot-copy-manifest.json
a31bd7fc37753688feaa19e0bf518fb1fdcf5d5743a2fb87ac3d4625ec2ea380  ${SOURCE_REL}/evidence-manifest.txt
SOURCE_SHAS

mkdir "$EVIDENCE_ROOT"
mkdir "$PACKET_ROOT"
mkdir "$CANDIDATE_ROOT"
mkdir "$LOG_ROOT"

"$PYTHON_BIN" - \
  "$REPO_ROOT" \
  "$SOURCE_ROOT" \
  "$EVIDENCE_ROOT" \
  "$EVIDENCE_REL" \
  "$CANDIDATE_ROOT" \
  "$LOG_ROOT" <<'PY'

from __future__ import annotations

import base64
import hashlib
import json
import os
import stat
import subprocess
import sys
from pathlib import Path

repo_root = Path(sys.argv[1]).resolve(strict=True)
source_root = Path(sys.argv[2]).resolve(strict=True)
evidence_root = Path(sys.argv[3]).resolve(strict=True)
evidence_rel = sys.argv[4]
candidate_root = Path(sys.argv[5]).resolve(strict=True)
log_root = Path(sys.argv[6]).resolve(strict=True)
packet_root = candidate_root.parent

payload = json.loads(
    base64.b64decode("", validate=True).decode("utf-8")
)
approval_text = base64.b64decode(
    "", validate=True
).decode("utf-8")

target = "/etc/sudoers.d/ai-media-os-3e-j-root-helper"

protected_sha = {
    "data/database/ebook_affiliate.db": (
        "1a421bd32edf1e9eedebc90cfd1b588b1ca0745670c6372c146a99b154e374e9"
    ),
    "config/slack_worker_release_source_manifest.json": (
        "ea201edeba978e1d0b3cf6219cc16efac8641567216885c5a245c66e99fc9c2d"
    ),
    "app/db/repositories/workflow_state_repository.py": (
        "00241611109dc51d44c8e23f2b0940c10f5488bf7cd4061597284679bdcfd90e"
    ),
    "migrations/versions/00241611109d_add_unique_wordpress_post_id.py": (
        "e1d29ed34fdbcaedb4a811681d8c28534682f8ce2d1144d044c0cb6dd0f3054a"
    ),
    "scripts/run_slack_approval_socket.py": (
        "c2ab37a7e86fbdca79a456ed17a8c55b20fdd0dc0f8e1f3b426f0ba75cebe3e6"
    ),
    "tests/test_slack_approval_socket_hold_remediation_offline.py": (
        "86dfc01686ffd53a2c6c7e73192d469db5040bc38f6541031cb6f36e7846ed72"
    ),
}

def require(condition: bool, message: str) -> None:
    if not condition:
        raise AssertionError(message)

def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def write_exclusive(path: Path, data: bytes, mode: int = 0o640) -> None:
    descriptor = os.open(
        path,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
        mode,
    )
    with os.fdopen(descriptor, "wb", closefd=True) as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())

# Verify the sealed R2-R7 source.
source_files = [p for p in source_root.rglob("*") if p.is_file()]
source_dirs = [source_root] + [
    p for p in source_root.rglob("*") if p.is_dir()
]
require(len(source_files) == 39, "SOURCE_R2_R7_FILE_COUNT_NOT_39")
require(len(source_dirs) == 10, "SOURCE_R2_R7_DIRECTORY_COUNT_NOT_10")
require(
    not any(p.is_symlink() for p in source_root.rglob("*")),
    "SOURCE_R2_R7_SYMLINK",
)
require(
    all(stat.S_IMODE(p.lstat().st_mode) == 0o444 for p in source_files),
    "SOURCE_R2_R7_FILE_MODE_NOT_0444",
)
require(
    all(stat.S_IMODE(p.lstat().st_mode) == 0o555 for p in source_dirs),
    "SOURCE_R2_R7_DIRECTORY_MODE_NOT_0555",
)

source_fixed = {
    "result.json": (
        "ff696c3857c9b9624ec8bb76b7eb668f2a90285825711f4cb3fdcbcc48f048c1"
    ),
    "seal-validation.json": (
        "a8927081753839939f752256fa7edbe0dbad1816341cb34a32484a325ab96e1d"
    ),
    "snapshot-copy-manifest.json": (
        "d6b71537bae70fa0f4e9ae2a6b9b214881ec11e0190e440782c9da0a71d9afc3"
    ),
    "evidence-manifest.txt": (
        "a31bd7fc37753688feaa19e0bf518fb1fdcf5d5743a2fb87ac3d4625ec2ea380"
    ),
}
for relative, expected in source_fixed.items():
    require(
        sha256(source_root / relative) == expected,
        f"SOURCE_R2_R7_SHA:{relative}",
    )

source_manifest_path = source_root / "evidence-manifest.txt"
source_manifest_entries = {}
for line in source_manifest_path.read_text(encoding="utf-8").splitlines():
    digest, relative = line.split("  ", 1)
    require(relative not in source_manifest_entries, "SOURCE_MANIFEST_DUPLICATE")
    source_manifest_entries[relative] = digest
require(len(source_manifest_entries) == 38, "SOURCE_MANIFEST_COUNT_NOT_38")
for relative, digest in source_manifest_entries.items():
    require(
        sha256(source_root / relative) == digest,
        f"SOURCE_MANIFEST_SHA:{relative}",
    )

protected_before = {}
for relative, expected in protected_sha.items():
    actual = sha256(repo_root / relative)
    require(actual == expected, f"PROTECTED_SHA_BEFORE:{relative}")
    protected_before[relative] = actual

# Decode candidate artifacts exclusively.
for name, encoded in payload.items():
    require("/" not in name and name not in {".", ".."}, "PAYLOAD_NAME")
    write_exclusive(
        candidate_root / name,
        base64.b64decode(encoded, validate=True),
    )

manifest = json.loads(
    (candidate_root / "candidate-manifest.json").read_text(encoding="utf-8")
)
require(manifest["phase"] == "TST-5D-W2B-I2F-3E-J-R2-R8", "MANIFEST_PHASE")
require(manifest["file_count_excluding_manifest"] == 7, "MANIFEST_COUNT")
require(manifest["root_readonly_verification_executed"] is False, "MANIFEST_EXEC")
require(manifest["sudo_execution_performed"] is False, "MANIFEST_SUDO")
require(manifest["sudoers_changed"] is False, "MANIFEST_SUDOERS")
for item in manifest["files"]:
    artifact = candidate_root / item["name"]
    require(artifact.is_file(), f"ARTIFACT_MISSING:{item['name']}")
    require(
        sha256(artifact) == item["sha256"],
        f"ARTIFACT_SHA:{item['name']}",
    )
    require(
        artifact.stat().st_size == item["size_bytes"],
        f"ARTIFACT_SIZE:{item['name']}",
    )

# Syntax and semantic validation only. Never execute the verifier.
bash_log = log_root / "verifier-bash-n.log"
with bash_log.open("wb") as stream:
    check = subprocess.run(
        [
            "bash",
            "-n",
            str(
                candidate_root
                / "root_readonly_sudoers_destination_verifier.sh"
            ),
        ],
        stdout=stream,
        stderr=subprocess.STDOUT,
        check=False,
    )
require(check.returncode == 0, "VERIFIER_BASH_N_FAILED")

compile_log = log_root / "python-compile.log"
compile_lines = []
for name in (
    "validate_r2_r8_packet.py",
    "test_r2_r8_packet_negative.py",
):
    check = subprocess.run(
        [
            str(repo_root / ".venv/bin/python"),
            "-m",
            "py_compile",
            str(candidate_root / name),
        ],
        text=True,
        capture_output=True,
        check=False,
    )
    require(check.returncode == 0, f"PY_COMPILE:{name}")
    compile_lines.append(f"PYTHON_COMPILE_PASS={name}")
write_exclusive(
    compile_log,
    ("\n".join(compile_lines) + "\n").encode("utf-8"),
)

validator_log = log_root / "validator.log"
with validator_log.open("wb") as stream:
    check = subprocess.run(
        [
            str(repo_root / ".venv/bin/python"),
            str(candidate_root / "validate_r2_r8_packet.py"),
            str(candidate_root),
        ],
        stdout=stream,
        stderr=subprocess.STDOUT,
        check=False,
    )
require(check.returncode == 0, "VALIDATOR_FAILED")

negative_log = log_root / "negative-tests.log"
with negative_log.open("wb") as stream:
    check = subprocess.run(
        [
            str(repo_root / ".venv/bin/python"),
            str(candidate_root / "test_r2_r8_packet_negative.py"),
        ],
        cwd=candidate_root,
        stdout=stream,
        stderr=subprocess.STDOUT,
        check=False,
    )
require(check.returncode == 0, "NEGATIVE_TESTS_FAILED")
negative_text = negative_log.read_text(encoding="utf-8")
negative_lines = [line.strip() for line in negative_text.splitlines()]
require("Ran 12 tests" in negative_text, "NEGATIVE_TEST_COUNT_NOT_12")
require(negative_lines.count("OK") == 1, "NEGATIVE_TEST_OK_COUNT")

write_exclusive(
    packet_root / "human-approval-verbatim.txt",
    approval_text.encode("utf-8"),
)

packet_files = []
for path in sorted(packet_root.rglob("*")):
    if path.is_file():
        packet_files.append(
            {
                "name": path.relative_to(packet_root).as_posix(),
                "sha256": sha256(path),
                "size_bytes": path.stat().st_size,
            }
        )

packet_manifest = {
    "schema_version": "1.0",
    "phase": "TST-5D-W2B-I2F-3E-J-R2-R8",
    "status": "ROOT_READONLY_VERIFICATION_PACKET_PREPARED_NO_EXECUTION",
    "target_path": target,
    "packet_file_count_excluding_manifest": len(packet_files),
    "packet_files": packet_files,
    "root_readonly_verification_executed": False,
    "sudo_execution_performed": False,
    "sudoers_changed": False,
    "candidate_deployed_to_production": False,
    "runner_status": "BLOCKED_UNTIL_EXPLICIT_FINAL_EXECUTION_APPROVAL",
}
write_exclusive(
    packet_root / "packet-manifest.json",
    (
        json.dumps(
            packet_manifest,
            ensure_ascii=False,
            sort_keys=True,
            indent=2,
        )
        + "\n"
    ).encode("utf-8"),
)

protected_after = {}
for relative, expected in protected_sha.items():
    actual = sha256(repo_root / relative)
    require(actual == expected, f"PROTECTED_SHA_AFTER:{relative}")
    protected_after[relative] = actual
require(protected_after == protected_before, "PROTECTED_SHA_CHANGED")

result = {
    "schema_version": "1.0",
    "phase": "TST-5D-W2B-I2F-3E-J-R2-R8",
    "result": (
        "PASS_W2B_I2F3E_J_R2_R8_ROOT_READONLY_VERIFICATION_"
        "PACKET_PREPARED_NO_EXECUTION"
    ),
    "evidence_root": evidence_rel,
    "source_r2_r7_fixed_sha_review": "PASS",
    "source_r2_r7_seal_review": "PASS",
    "target_path": target,
    "candidate_file_count": 8,
    "negative_test_count": 12,
    "validator": "PASS",
    "verifier_bash_n": "PASS",
    "root_readonly_verification_executed": False,
    "sudo_execution_performed": False,
    "sudoers_changed": False,
    "candidate_deployed_to_production": False,
    "production_directory_created": False,
    "production_file_created": False,
    "production_process_signal_sent": False,
    "production_database_sql_connection_used": False,
    "production_backup_created": False,
    "migration_executed": False,
    "external_network_used": False,
    "final_approval_token_created": False,
    "approval_binding_created": False,
    "runner_status": "BLOCKED_UNTIL_EXPLICIT_FINAL_EXECUTION_APPROVAL",
    "writer_freeze_execution": "HOLD",
    "production_release_decision": "HOLD",
    "release_status": "CANDIDATE_NOT_APPROVED",
    "evidence_seal_performed": False,
    "evidence_seal_status": "NOT_PERFORMED_CHMOD_NOT_AUTHORIZED",
    "protected_sha_unchanged": True,
    "next_gate": (
        "HUMAN_REVIEW_3E_J_R2_R8_ROOT_READONLY_VERIFICATION_PACKET"
    ),
}
write_exclusive(
    evidence_root / "result.json",
    (
        json.dumps(result, ensure_ascii=False, sort_keys=True, indent=2)
        + "\n"
    ).encode("utf-8"),
)

manifest_entries = []
for path in sorted(evidence_root.rglob("*")):
    if path.is_file() and path.name != "evidence-manifest.txt":
        manifest_entries.append(
            f"{sha256(path)}  "
            f"{path.relative_to(evidence_root).as_posix()}"
        )
write_exclusive(
    evidence_root / "evidence-manifest.txt",
    ("\n".join(manifest_entries) + "\n").encode("utf-8"),
)

print(f"RESULT={result['result']}")
print(f"EVIDENCE_ROOT={evidence_rel}")
print("SOURCE_R2_R7_FIXED_SHA_REVIEW=PASS")
print("SOURCE_R2_R7_SEAL_REVIEW=PASS")
print(f"TARGET_PATH={target}")
print("CANDIDATE_FILE_COUNT=8")
print("NEGATIVE_TEST_COUNT=12")
print("NEGATIVE_TESTS=PASS")
print("VALIDATOR=PASS")
print("VERIFIER_BASH_N=PASS")
print("ROOT_READONLY_VERIFICATION_EXECUTED=false")
print("SUDO_EXECUTION_PERFORMED=false")
print("SUDOERS_CHANGED=false")
print("CANDIDATE_DEPLOYED_TO_PRODUCTION=false")
print("PRODUCTION_DIRECTORY_CREATED=false")
print("PRODUCTION_FILE_CREATED=false")
print("PRODUCTION_PROCESS_SIGNAL_SENT=false")
print("PRODUCTION_DB_SQL_CONNECTION_USED=false")
print("PRODUCTION_BACKUP_CREATED=false")
print("MIGRATION_EXECUTED=false")
print("EXTERNAL_NETWORK_USED=false")
print("FINAL_APPROVAL_TOKEN_CREATED=false")
print("APPROVAL_BINDING_CREATED=false")
print("PROTECTED_SHA_UNCHANGED=true")
print("RUNNER_STATUS=BLOCKED_UNTIL_EXPLICIT_FINAL_EXECUTION_APPROVAL")
print("WRITER_FREEZE_EXECUTION=HOLD")
print("PRODUCTION_RELEASE_DECISION=HOLD")
print("RELEASE_STATUS=CANDIDATE_NOT_APPROVED")
print("EVIDENCE_SEAL_PERFORMED=false")
print("EVIDENCE_SEAL_STATUS=NOT_PERFORMED_CHMOD_NOT_AUTHORIZED")
print(
    "NEXT_GATE="
    "HUMAN_REVIEW_3E_J_R2_R8_ROOT_READONLY_VERIFICATION_PACKET"
)
print(f"RESULT_SHA={sha256(evidence_root / 'result.json')}")
print(
    f"PACKET_MANIFEST_SHA="
    f"{sha256(packet_root / 'packet-manifest.json')}"
)
print(
    f"EVIDENCE_MANIFEST_SHA="
    f"{sha256(evidence_root / 'evidence-manifest.txt')}"
)

PY

printf 'SCRIPT_EXIT_CODE=0\n'
